import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../data/app_state.dart';import '../theme/app_theme.dart';
class ShopOffersScreen extends StatefulWidget{const ShopOffersScreen({super.key});@override State<ShopOffersScreen> createState()=>_ShopOffersScreenState();}
class _ShopOffersScreenState extends State<ShopOffersScreen>{List<Map<String,dynamic>> _offers=[];bool _loading=true;Future<void> _load()async{final uid=Supabase.instance.client.auth.currentUser!.id;final rows=await Supabase.instance.client.from('shop_offers').select('*,shop_offer_items(listing_id)').eq('shop_id',uid).order('starts_at',ascending:false);if(mounted)setState(()=>_offers=List<Map<String,dynamic>>.from(rows));setState(()=>_loading=false);}
@override void initState(){super.initState();_load();}
Future<void> _add()async{final title=TextEditingController(),discount=TextEditingController();DateTime start=DateTime.now(),end=DateTime.now().add(const Duration(days:1));final state=context.read<AppState>();final active=state.listings.where((x)=>x.seller.id==state.currentUser?.id&&x.status.name=='active'&&!x.priceOnCall).toList();final selected=<String>{};await showDialog(context:context,builder:(d)=>StatefulBuilder(builder:(d,set){return AlertDialog(title:const Text('إنشاء عرض'),content:SizedBox(width:420,child:ListView(shrinkWrap:true,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'العنوان')),TextField(controller:discount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'نسبة الخصم 1-90%')),const SizedBox(height:8),...active.map((x)=>CheckboxListTile(value:selected.contains(x.id),onChanged:(v)=>set(()=>v==true?selected.add(x.id):selected.remove(x.id)),title:Text(x.title))),Text('البداية: '+start.toString()),Text('النهاية: '+end.toString())])),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('إلغاء')),ElevatedButton(onPressed:()async{final p=int.tryParse(discount.text);if(title.text.trim().isEmpty||p==null||p<1||p>90||selected.isEmpty)return;final offer=await Supabase.instance.client.from('shop_offers').insert({'shop_id':state.currentUser!.id,'title':title.text.trim(),'discount_percent':p,'starts_at':start.toUtc().toIso8601String(),'ends_at':end.toUtc().toIso8601String()}).select('id').single();await Supabase.instance.client.from('shop_offer_items').insert(selected.map((id)=>{'offer_id':offer['id'],'listing_id':id}).toList());if(d.mounted)Navigator.pop(d);_load();},child:const Text('حفظ'))]));});title.dispose();discount.dispose();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('عروض المعرض')),body:_loading?const Center(child:CircularProgressIndicator(color:AppColors.gold)):ListView(padding:const EdgeInsets.all(12),children:[ElevatedButton.icon(onPressed:_add,icon:const Icon(Icons.add),label:const Text('إنشاء عرض')), ..._offers.map((x)=>Card(child:ListTile(title:Text(x['title']),subtitle:Text('-'+x['discount_percent'].toString()+'% • '+x['starts_at'].toString()+' → '+x['ends_at'].toString()),trailing:IconButton(onPressed:()async{await Supabase.instance.client.from('shop_offers').delete().eq('id',x['id']);_load();},icon:const Icon(Icons.delete_outline))))]) );}
}